  "a streaming service": "خدمة البث هذه",
  "this site": "هذا الموقع",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "هذا رابط بث مباشر (.m3u8) — يُرسَل على أجزاء ولا يمكن حفظه كملف واحد.",
  "Downloading works in the Android app.": "التنزيل متاح في تطبيق أندرويد.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "لم يُتِح Google Drive الملف — تأكد أنه مشارك مع «أي شخص لديه الرابط».",
  "This page plays a {site} video, which can't be downloaded.": "تعرض هذه الصفحة فيديو من {site}، ولا يمكن تنزيله.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "تبث هذه الصفحة الفيديو على أجزاء (HLS)، ولا يمكن حفظه كملف واحد.",
  "No downloadable video was found on that page.": "لم يُعثر على فيديو قابل للتنزيل في هذه الصفحة.",
  "That link didn't give a video file (the site sent {t}).": "لم يُرجع هذا الرابط ملف فيديو (أرسل الموقع {t}).",
  "No downloadable video was found there.": "لم يُعثر على فيديو قابل للتنزيل هناك.",
  "Free includes 3 video downloads a day — Pro is unlimited": "الخطة المجانية تتضمن 3 تنزيلات فيديو يوميًا — وPro بلا حدود",
  "Downloading — you can close Attune, it keeps going": "جارٍ التنزيل — يمكنك إغلاق Attune وسيستمر",
  "The file was moved or deleted": "نُقل الملف أو حُذف",
  "The download failed — the link may have expired. Find it again and retry.": "فشل التنزيل — ربما انتهت صلاحية الرابط. ابحث عنه مرة أخرى وأعد المحاولة.",
  "PDF, Word, PowerPoint, Excel, photos — 80+ conversions, and translation": "PDF وWord وPowerPoint وExcel والصور — أكثر من 80 نوع تحويل، والترجمة",
  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word، وPowerPoint ← PDF، والصور ← PDF، والأوراق الممسوحة ضوئيًا ← Word قابل للتعديل، وExcel ↔ CSV ↔ JSON، والكتب الإلكترونية، وصفحات الويب، والترجمات النصية للأفلام، ودمج ملفات PDF وتقسيمها — على هاتفك. لا تُرفع ملفاتك أبدًا إلى موقع تحويل.",
  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · Word · PowerPoint · Excel · CSV · صور · كتب إلكترونية · صفحات ويب · ترجمات أفلام — عدة صور ← PDF واحد، وعدة ملفات PDF ← ملف مدمج",
  "That kind of file can't be converted here yet. Try PDF, Word, PowerPoint, Excel, CSV, photos, text, e-books, web pages or subtitles.": "لا يمكن تحويل هذا النوع من الملفات هنا بعد. جرّب PDF أو Word أو PowerPoint أو Excel أو CSV أو الصور أو النصوص أو الكتب الإلكترونية أو صفحات الويب أو ملفات الترجمة.",
  "Pick one file — or several photos (→ one PDF), or several PDFs (→ merged).": "اختر ملفًا واحدًا — أو عدة صور (← PDF واحد)، أو عدة ملفات PDF (← ملف مدمج).",
