  "This PDF is locked with a password — open it, save a copy without the password, and try again.": "ملف PDF هذا محمي بكلمة مرور — افتحه واحفظ نسخة بدون كلمة المرور، ثم أعد المحاولة.",
  "That file isn't a Word / Excel file (not a zip).": "هذا الملف ليس ملف Word / Excel.",
  "That file isn't a Word document.": "هذا الملف ليس مستند Word.",
  "That file isn't an Excel workbook.": "هذا الملف ليس مصنّف Excel.",
  "Unlimited file conversions, including scanned paper → editable Word": "تحويل الملفات بلا حدود، بما في ذلك الأوراق الممسوحة ضوئيًا ← Word قابل للتعديل",
  "Unlimited Chat X-Rays: who owes you, promises and unanswered questions in your WhatsApp chats": "فحص محادثات بلا حدود: من يدين لك، والوعود، والأسئلة التي لم يُرد عليها في محادثات واتساب",
  "Chat X-Ray": "فحص المحادثة",
  "Money, promises & questions in a WhatsApp chat": "الأموال والوعود والأسئلة في محادثة واتساب",
  "Who owes whom, what was promised, which dates were agreed and which questions got no answer — read from a WhatsApp chat on your phone. The chat never leaves the phone.": "من يدين لمن، وما الذي وُعد به، وأي مواعيد اتُّفق عليها، وأي أسئلة لم يُرد عليها — من محادثة واتساب على هاتفك. لا تغادر المحادثة الهاتف أبدًا.",
  "In WhatsApp, open the chat → ⋮ → More → Export chat → Without media.": "في واتساب: افتح المحادثة ← ⋮ ← المزيد ← تصدير الدردشة ← بدون وسائط.",
  "Pick Attune in the share list — or save the file and choose it here.": "اختر Attune من قائمة المشاركة — أو احفظ الملف واختره من هنا.",
  "Choose the exported chat (.txt)": "اختر المحادثة المُصدَّرة (.txt)",
