  "No money owed or paid was found in this part of the chat.": "لم يُعثر على أموال مستحقة أو مدفوعة في هذا الجزء من المحادثة.",
  "Totals are added up by the phone from the messages quoted — check them before asking anyone to pay.": "يجمع الهاتف الإجماليات من الرسائل المقتبسة — راجعها قبل مطالبة أي شخص بالدفع.",
  "Promise": "وعد",
  "No promises or dates were found.": "لم يُعثر على وعود أو مواعيد.",
  "Every question to you got an answer. 👍": "كل سؤال وُجّه إليك تمت الإجابة عنه. 👍",
