  "Check another deal": "فحص صفقة أخرى",
  "Unlimited Deal Checks: the real cost, the market price and scam signs before you pay": "فحص الصفقات بلا حدود: التكلفة الحقيقية وسعر السوق وعلامات الاحتيال قبل أن تدفع",
  "Deal Check": "فحص الصفقة",
  "Before you pay or sign": "قبل أن تدفع أو توقّع",
  "Before you pay or sign: paste the offer, the seller's message or an installment plan — or add a screenshot. Attune works out the real cost, checks the market price, looks for scam signs and writes your reply.": "قبل أن تدفع أو توقّع: الصق العرض أو رسالة البائع أو خطة التقسيط — أو أضف لقطة شاشة. يحسب Attune التكلفة الحقيقية، ويقارنها بسعر السوق، ويبحث عن علامات الاحتيال، ويكتب لك الرد.",
  "e.g. “iPhone 15 Pro 256GB, like new, 38,000 EGP, deposit on Vodafone Cash to hold it”  ·  “12,400 EGP or 3 × 4,133 with valU”": "مثلًا: «آيفون 15 برو 256 جيجا، بحالة الجديد، 38,000 جنيه، عربون على فودافون كاش للحجز»  ·  «12,400 جنيه أو 3 × 4,133 مع valU»",
