  "Settings": "الإعدادات",
  "Instant does one quick job on any text or photo — answer it, rewrite it, translate it, summarise it — without starting a chat. For a conversation use Chat; for places near you, Instant hands you to the map.": "ينفّذ «فوري» مهمة سريعة واحدة على أي نص أو صورة — يجيب عنه أو يعيد صياغته أو يترجمه أو يلخّصه — دون بدء محادثة. للحوار استخدم «المحادثة»؛ وللأماكن القريبة منك ينقلك «فوري» إلى الخريطة.",
