  "Your own recipes for the AI — create, import, share": "وصفاتك الخاصة للذكاء الاصطناعي — أنشئ واستورد وشارك",
  "Your own recipes for the AI: how to write your quotes, replies, lessons. Start a message with a skill's command, or let the app pick it when your question fits. A skill adds instructions, facts and a checklist to your question; a small program inside it (only if you keep one) runs offline in a locked box.": "وصفاتك الخاصة للذكاء الاصطناعي: كيف يكتب عروض أسعارك وردودك ودروسك. ابدأ رسالتك بأمر المهارة، أو دع التطبيق يختارها عندما يناسبها سؤالك. تضيف المهارة إلى سؤالك تعليمات ومعلومات وقائمة مراجعة؛ وإن احتفظت ببرنامج صغير داخلها فإنه يعمل بدون إنترنت داخل بيئة معزولة.",
