  "Start a message with it to use this skill, e.g. “/quote 50 t crane for 3 days”.": "ابدأ رسالة به لاستخدام هذه المهارة، مثلًا «/quote رافعة 50 طنًا لمدة 3 أيام».",
  "When to use it": "متى تُستخدم",
  "Words that tell the app this skill fits: crane quote, price offer, rental…": "كلمات تُخبر التطبيق أن هذه المهارة مناسبة: عرض سعر رافعة، تأجير…",
  "The app uses these words to pick the skill by itself when your question fits.": "يستخدم التطبيق هذه الكلمات لاختيار المهارة تلقائيًا عندما يناسبها سؤالك.",
