  "A photo is read word for word and the text kept, so a whiteboard, a receipt or a handwritten site note becomes searchable — and anything promised on it shows up on the right.": "الصورة تُقرأ كلمة بكلمة ويُحفظ نصها، فتصبح السبورة أو الإيصال أو ملاحظة الموقع المكتوبة بخط اليد قابلة للبحث — وأي وعد مكتوب فيها يظهر على اليمين.",
  "Your words": "كلماتك",
  "The words your trade uses, that a general model gets wrong every time. Teach it once and it never gets them wrong again — in answers, documents and translations alike. This is the part of the app that gets better the longer you use it, and the part nobody can copy.": "الكلمات التي يستخدمها مجال عملك، والتي يخطئ فيها النموذج العام في كل مرة. علّمه إياها مرة واحدة ولن يخطئ فيها مجددًا — في الإجابات والمستندات والترجمات. هذا هو الجزء من التطبيق الذي يتحسّن كلما استخدمته، ولا يستطيع أحد نسخه.",
  "the word (سطحة, mobilisation…)": "الكلمة (سطحة، mobilisation…)",
