  "Only flagged, never removed on its own — it's your vocabulary, not ours.": "نُنبّه فقط، ولا نحذف شيئًا تلقائيًا — إنها مفرداتك، لا مفرداتنا.",
  "You keep using these — should it know them?": "تستخدم هذه الكلمات كثيرًا — هل تريد أن يتعلّمها؟",
