  "Nothing yet. The fastest way to start: when an answer uses the wrong word, tap “a word is wrong” under it.": "لا شيء بعد. أسرع طريقة للبدء: عندما تستخدم إجابةٌ كلمة خاطئة، اضغط «كلمة خاطئة» تحتها.",
