  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "مثلًا: السائق لا يريد تشغيل العدّاد، ماذا أقول؟ / هل هذا السعر عادل لسجادة؟ / هل يمكن شرب ماء الصنبور؟",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "يعرف كيف تسير الأمور فعلًا هنا — الأسعار العادلة، والمبالغة الشائعة في الأسعار، وما يُعدّ غير لائق. وسيخبرك عندما يحتاج أمرٌ ما إلى بيانات حيّة لا تتوفر بدون إنترنت.",
  "Say it now": "قلها الآن",
