  "Copied — show it to them": "نُسخت — اعرضها عليهم",
  "Tap to copy. These are written by hand, not generated — so an allergy or emergency phrase can never come out wrong.": "اضغط للنسخ. هذه العبارات مكتوبة يدويًا، لا مولَّدة — فلا يمكن أن تخرج عبارة الحساسية أو الطوارئ خاطئة.",
