  "Speak or type it roughly, in any language. e.g. 'crane 3 hydraulic leak at north gate around 2pm, stopped work, called maintenance, no injuries'": "تحدّث أو اكتبها بشكل تقريبي، بأي لغة. مثلًا: «الرافعة 3 بها تسريب هيدروليكي عند البوابة الشمالية نحو الثانية ظهرًا، أوقفنا العمل، واتصلنا بالصيانة، ولا إصابات»",
