  "Document": "المستند",
  "Needs:": "يحتاج:",
  ". Only genuinely essential gaps are flagged — today's date and your name are filled in automatically.": ". لا نُنبّه إلا على النواقص الضرورية فعلًا — يُملأ تاريخ اليوم واسمك تلقائيًا.",
  "Produce it in": "إنشاؤه بـ",
