  "Rough note in, finished record out — structured, in every language the site needs, without a signal.": "ملاحظة تقريبية تدخل، وسجل نهائي يخرج — منظَّم، وبكل لغة يحتاجها الموقع، دون شبكة.",
  "Runs on the device. Nothing about the incident leaves the phone.": "يعمل على الجهاز. لا شيء عن الحادثة يغادر الهاتف.",
