  "Open site memory →": "فتح ذاكرة الموقع ←",
  "Reviewer's read": "قراءة المراجِع",
  "Text to rewrite": "النص المراد إعادة كتابته",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "الصق نصًا مولَّدًا بالذكاء الاصطناعي أو جامدًا — ليعود وكأن إنسانًا كتبه.",
  "Your writing sample": "عيّنة من كتابتك",
  "(this is what makes it sound like you)": "(هذا ما يجعله يشبهك)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "الصق بضع فقرات كتبتها بنفسك — بريد، رسالة، أي شيء بأسلوبك الطبيعي.",
  "Rewriting…": "جارٍ إعادة الكتابة…",
  "Humanize": "إضفاء طابع بشري",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "يحافظ على معناك وحقائقك تمامًا — ولا يغيّر إلا أسلوب القراءة. عيّنة الكتابة اختيارية لكنها تُحدث الفرق الأكبر.",
  "Rewritten": "أُعيدت كتابته",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "الصق نصًا جامدًا أو يبدو مكتوبًا بالذكاء الاصطناعي، وأضف عيّنة من كتابتك، ليعود بأسلوبك — المعنى نفسه، بإيقاع إنساني.",
