  "Optimize my prompt": "تحسين طلبي",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "الحلقة: اكتب ما تريد ← احصل على طلب محسّن ← أرسله ← أعِد الرد ← يصبح كل طلب تالٍ أدق. في تطبيق الهاتف، تغني قائمة المشاركة عن النسخ واللصق تمامًا.",
  "· older turns compacted": "· ضُغطت الأدوار الأقدم",
  " · getting tight": " · المساحة تضيق",
  "Ready prompt recipes — pick one, fill the blanks, then": "وصفات طلبات جاهزة — اختر واحدة، املأ الفراغات، ثم",
