  "devices, is checked on the device so it activates on a plane, and sends nothing about you — only a random install id, only when you activate.": "أجهزة، ويُتحقّق منه على الجهاز نفسه فيُفعَّل حتى في الطائرة، ولا يرسل أي معلومات عنك — فقط رقم تثبيت عشوائي، وعند التفعيل فقط.",
  "Set up — Attune now fits how you work": "تم الإعداد — أصبح Attune مناسبًا لطريقة عملك",
