  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "الأوزان المثبَّتة لا تتحدّث من تلقاء نفسها، فالطلب الذي يعمل اليوم سيعمل بالطريقة نفسها بعد سنة. وتُثبت البصمة أي ملف بالضبط هو الذي يجيب.",
