  "e.g. You work for a crane-rental company in Egypt. Answer in Egyptian Arabic unless I write in English. Give lifting capacities in tonnes.": "مثلًا: أنت تعمل لدى شركة لتأجير الرافعات في مصر. أجب بالعامية المصرية إلا إذا كتبت بالإنجليزية. اذكر أحمال الرفع بالطن.",
  "Saved when you tap outside the box. Stays on this phone.": "يُحفظ عند الضغط خارج المربع. ويبقى على هذا الهاتف.",
  "Web lookup": "البحث على الويب",
  "Brave Search API key": "مفتاح Brave Search API",
  "Get one at api-dashboard.search.brave.com. Stored only on this phone. Falls back to DuckDuckGo if Brave refuses.": "احصل عليه من api-dashboard.search.brave.com. يُحفظ على هذا الهاتف فقط. ويُستخدم DuckDuckGo إذا رفض Brave الطلب.",
  "Reads DuckDuckGo's results from your phone and opens the top pages, so answers come from real passages. DuckDuckGo has no official API and can occasionally rate-limit; Brave is the dependable route.": "يقرأ نتائج DuckDuckGo من هاتفك ويفتح أهم الصفحات، فتأتي الإجابات من فقرات حقيقية. لا يوفّر DuckDuckGo واجهة برمجية رسمية وقد يحدّ الطلبات أحيانًا؛ أما Brave فهو الخيار الموثوق.",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "لا يغادر الهاتف إلا السؤال الذي تبحث عنه والصفحات التي تُفتح — وليس محادثتك أو ملفاتك أو ذاكرتك أبدًا.",
  "Privacy": "الخصوصية",
  "Hide network log": "إخفاء سجل الشبكة",
  "Network log": "سجل الشبكة",
  "made ·": "اتصال ·",
  "blocked · this session": "محظور · في هذه الجلسة",
  "Nothing has left the phone.": "لم يغادر شيء الهاتف.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "النموذج نفسه لا يستخدم الشبكة أبدًا. يعرض السجل كل اتصال أجراه التطبيق أو رفضه، بالعنوان والسبب فقط — وهو الدليل على أن «لا شيء يغادر هذا الهاتف».",
  "Engine": "المحرك",
  "Run the AI on your own hardware. Nothing leaves the device, nothing costs per use.": "شغّل الذكاء الاصطناعي على جهازك. لا شيء يغادر الجهاز، ولا تكلفة لكل استخدام.",
  "This device": "هذا الجهاز",
  "Load a model to start": "حمّل نموذجًا للبدء",
  "Read directly from this phone — exact, not estimated.": "مقروءة مباشرة من هذا الهاتف — دقيقة، لا تقديرية.",
  "Using the figure you gave.": "باستخدام الرقم الذي أدخلته.",
