  "Parity: unverified until this tier passes its eval set — ✓ appears only after it does.": "التكافؤ: غير مُتحقَّق منه حتى تجتاز هذه الفئة مجموعة التقييم — ولا تظهر ✓ إلا بعد ذلك.",
  "Needs": "يحتاج",
