  "GB (mmap)": "جيجابايت (mmap)",
  "KV": "KV",
  "% cache": "% ذاكرة مؤقتة",
  "GB total": "جيجابايت إجمالي",
  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "ذاكرة KV بدقة INT4 مع حذف الأقدم بنافذة منزلقة، فلا تكبر المحادثات الطويلة بلا حد.",
  "Storage:": "التخزين:",
  "Compute": "المعالجة",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "تجري المعالجة الأولية حيث تكون الحوسبة أسرع، والتوليد حيث يكون عرض النطاق أكبر. استخدام الاثنين يرفع عرض النطاق الفعلي من ~43 إلى 59 جيجابايت/ث.",
  "Task adapters": "محوّلات المهام",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "تعديلات صغيرة لكل مهمة — وهذا ما يجعل نموذجًا بحجم الهاتف يقدّم أكثر من حجمه. تُحمَّل فوق النموذج الأساسي، وحجم كل منها بضعة ميجابايت.",
  "MB": "ميجابايت",
  "Training data": "بيانات التدريب",
  "Each cloud answer is a worked example. Collected, they train the small adapters that bring on-device quality up to cloud level — and a slice is held back to prove it. Stored on this device only.": "كل إجابة سحابية مثال محلول. وعند جمعها تدرّب المحوّلات الصغيرة التي ترفع جودة الجهاز إلى مستوى السحابة — ويُحجز جزء منها لإثبات ذلك. محفوظة على هذا الجهاز فقط.",
  "Save my prompts as training data": "حفظ طلباتي كبيانات تدريب",
  " · ready": " · جاهز",
  "No training pairs yet": "لا توجد أزواج تدريب بعد",
  "Training set exported": "صُدِّرت مجموعة التدريب",
  "Export training set": "تصدير مجموعة التدريب",
  "No eval pairs yet": "لا توجد أزواج تقييم بعد",
  "Eval set exported": "صُدِّرت مجموعة التقييم",
