  "Training data cleared": "تم مسح بيانات التدريب",
  "Delete all": "حذف الكل",
  "pairs per feature before a tier can be judged. ~": "زوجًا لكل ميزة قبل إمكانية الحكم على الفئة. ~",
  "% is held back and never trained on, so the test stays honest.": "% يُحجز ولا يُستخدم في التدريب أبدًا، ليبقى الاختبار نزيهًا.",
  "Where it runs": "أين يعمل",
  "Loading the model into memory — large models take a minute": "جارٍ تحميل النموذج في الذاكرة — النماذج الكبيرة تستغرق دقيقة",
  "Model": "النموذج",
  "loaded — running locally": "مُحمَّل — يعمل محليًا",
  "Downloading model…": "جارٍ تنزيل النموذج…",
  "No model fits this device": "لا يوجد نموذج يناسب هذا الجهاز",
  "One download, then it works offline forever. On Wi-Fi this takes a few minutes; the model stays on your device.": "تنزيل واحد، ثم يعمل بدون إنترنت دائمًا. على Wi-Fi يستغرق بضع دقائق؛ ويبقى النموذج على جهازك.",
  "Your real names for your real things. Every document then uses them correctly — no invented equipment names, no wrong site spellings. Stays on your devices.": "الأسماء الحقيقية لأشيائك الحقيقية. تستخدمها كل المستندات بعد ذلك بشكل صحيح — بلا أسماء معدات مختلقة، ولا أخطاء في كتابة أسماء المواقع. تبقى على أجهزتك.",
  "Use company terminology": "استخدام مصطلحات الشركة",
  "Company name": "اسم الشركة",
