  "Sites / locations": "المواقع / الأماكن",
  "e.g. North Gate Yard, October Depot, Site B — Sheikh Zayed": "مثلًا: ساحة البوابة الشمالية، مخزن أكتوبر، الموقع B — الشيخ زايد",
  "Equipment / assets": "المعدات / الأصول",
  "e.g. LTM 1200 (unit 3), Demag AC 100, XCMG QY50KA — 'Crane 3' means unit 3": "مثلًا: LTM 1200 (الوحدة 3)، Demag AC 100، XCMG QY50KA — «الرافعة 3» تعني الوحدة 3",
  "Internal terms & abbreviations": "مصطلحات واختصارات داخلية",
  "e.g. PTW = permit to work, 'the yard' = North Gate, LO = lift operation": "مثلًا: PTW = تصريح عمل، «الساحة» = البوابة الشمالية، LO = عملية رفع",
  "Downtime cost / hour": "تكلفة التوقف / الساعة",
  "Currency": "العملة",
  "EGP": "جنيه",
  "Turns logged downtime into a figure you can put in front of management.": "يحوّل وقت التوقف المسجَّل إلى رقم تضعه أمام الإدارة.",
  "Reporting rules": "قواعد التقارير",
  "e.g. every incident must state whether work was stopped; always record permit number": "مثلًا: يجب أن تذكر كل حادثة هل توقف العمل؛ وسجّل رقم التصريح دائمًا",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "يُضاف هذا إلى كل مستند ميداني — وهو أيضًا ما يتدرّب عليه محوّلك الخاص، فيتعلّم النموذج طريقة عملك أنت، لا طريقة عامة.",
