  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "ستُستبدل محادثات هذا الهاتف ({c}) وقيود دفتره ({l}) بما في النسخة الاحتياطية. يمكنك التراجع مرة واحدة بعدها مباشرة.",
