  "Handles structure well; tags survive compression.": "يتعامل جيدًا مع البنية؛ وتبقى الوسوم بعد الضغط.",
  "Name the outcome; it fills in the path.": "حدِّد النتيجة المطلوبة؛ وهو يكمل الطريق.",
  "Huge window — compress for cost, not for fit.": "نافذة ضخمة — اضغط لتوفير التكلفة، لا لكي يتسع.",
  "Direct phrasing; ask for reasoning explicitly.": "صياغة مباشرة؛ اطلب التعليل صراحةً.",
  "Structured reasoning; keep numbered steps.": "تفكير منظّم؛ احتفظ بالخطوات المرقّمة.",
  "Strong multilingual — keep the source language.": "قوي متعدد اللغات — احتفظ بلغة المصدر.",
  "Concise by nature; over-compressing loses nuance.": "موجز بطبعه؛ والضغط الزائد يُفقد الفروق الدقيقة.",
  "Open weights; explicit instructions beat implied ones.": "أوزان مفتوحة؛ التعليمات الصريحة أفضل من الضمنية.",
  "Long documents are its strength; keep headings.": "المستندات الطويلة نقطة قوته؛ احتفظ بالعناوين.",
  "Code context competes for the window — trim prose first.": "سياق الكود يزاحم على النافذة — شذّب النص أولًا.",
  "A search tool — keep the sources, cut the styling.": "أداة بحث — احتفظ بالمصادر، واحذف التنسيق.",
  "On-device 1B": "على الجهاز 1B",
  "Tight. Cut everything that isn't the instruction.": "ضيّقة. احذف كل ما ليس تعليمات.",
  "On-device 3B": "على الجهاز 3B",
  "Room for a short history, not a long one.": "تتسع لسجل قصير، لا طويل.",
  "On-device 8B": "على الجهاز 8B",
  "Same window; better at using what's in it.": "النافذة نفسها؛ لكنه أفضل في استخدام ما فيها.",
  "Ed25519": "Ed25519",
  "Activated offline — it will bind to this device the next time there's a connection.": "فُعِّل بدون إنترنت — سيرتبط بهذا الجهاز في المرة القادمة التي يتوفر فيها اتصال.",
  "Couldn't reach activation — running on the key's signature for now.": "تعذّر الوصول إلى خادم التفعيل — يعمل حاليًا بتوقيع المفتاح.",
  "per month": "شهريًا",
  "cancel any time": "يمكنك الإلغاء في أي وقت",
