  "Stops invented facts": "يمنع اختلاق الحقائق",
  "No model is loaded. Open Engine in Attune and load one.": "لا يوجد نموذج محمَّل. افتح «المحرك» في Attune وحمّل نموذجًا.",
  "Attune does not answer that kind of request.": "لا يجيب Attune عن هذا النوع من الطلبات.",
  "Suggested. The free tier stops when it runs out instead of charging you.": "مُقترح. تتوقف الباقة المجانية عند نفادها بدلًا من أن تُحاسَب.",
  "Needs a card on file. An independent index — good in English, unproven in Arabic.": "يحتاج بطاقة دفع مسجّلة. فهرس مستقل — جيد بالإنجليزية، ولم يُختبر بالعربية.",
  "Returns Google's own results, so the best Arabic quality of the three.": "يُرجع نتائج Google نفسها، فهو الأفضل للعربية بين الثلاثة.",
