  "On-device": "على الجهاز",
  "The only mode. Nothing leaves this device.": "الوضع الوحيد. لا شيء يغادر هذا الجهاز.",
  "Write a polite reply to this message: ": "اكتب ردًا مهذبًا على هذه الرسالة: ",
