  "Summarise this in 3 bullets: ": "لخّص هذا في 3 نقاط: ",
  "What should I check on a mobile crane's outriggers before a 40 t lift?": "ماذا أفحص في أرجل التثبيت (Outriggers) للرافعة المتحركة قبل رفع 40 طنًا؟",
  "My period started this morning, medium flow": "بدأت الدورة صباح اليوم، والغزارة متوسطة",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "هل تريد إضافتها إلى دفترك في «المال»؟ ستختار الحساب وتؤكّد هناك.",
  "Spotting": "تنقيط",
