  "3 templates · 5 history items": "3 قوالب · 5 عناصر في السجل",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "معرفة نموذج 35B، و3B فقط تعمل على كل رمز — إجابات قريبة من أقوى النماذج بسرعة يتحملها الحاسوب المحمول. نموذج «خليط الخبراء» يُبقي كل الخبراء في الذاكرة رغم أن القليل منهم يعمل لكل رمز، لذلك يحتاج ذاكرة نموذج 35B وحوسبة نموذج 3B.",
  "A bigger length budget for reports, plans and analysis.": "مساحة أطول للتقارير والخطط والتحليلات.",
  "Always think before answering": "التفكير دائمًا قبل الإجابة",
  "Ask it as much as you like — no daily limit": "اسأله ما تشاء — بلا حد يومي",
  "Can run {m}": "يستطيع تشغيل {m}",
  "Detected about {n} GB of memory": "اكتُشفت ذاكرة بنحو {n} جيجابايت",
  "Your phone reports {n} GB of memory": "يُبلغ هاتفك عن ذاكرة {n} جيجابايت",
  "Your computer reports {n} GB of memory": "يُبلغ حاسوبك عن ذاكرة {n} جيجابايت",
  "which leaves plenty of room for long conversations": "وهذا يترك مساحة كبيرة للمحادثات الطويلة",
  "which is comfortable for everyday use": "وهذا مريح للاستخدام اليومي",
  "which is enough, with shorter conversations": "وهذا كافٍ، مع محادثات أقصر",
  ", ": "، ",
  "Documents, fleet records, copilot, every domain pack": "المستندات، سجلات الأسطول، المساعد، كل حزم المجالات",
  "Download it on Wi-Fi. After that it never uses your connection again.": "نزّله عبر Wi-Fi. بعد ذلك لن يستخدم اتصالك أبدًا.",
  "Small enough to download on mobile data if you need to.": "صغير بما يكفي لتنزيله عبر بيانات الهاتف إن احتجت.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "هذا نموذج كبير بالنسبة للهاتف. سيعمل، لكنه سيبطؤ بوضوح عندما يسخن الهاتف — اجعل الإجابات قصيرة، أو اختر النموذج الأصغر.",
  "Download {m} · {s} GB": "تنزيل {m} · {s} جيجابايت",
  "Every tool, and all 31 country packs": "كل الأدوات، وكل حزم الدول الـ31",
  "Finds what you promised people, from your own words": "يجد ما وعدت به الناس، من كلماتك أنت",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "عشوائية ثابتة، فيعطي سير العمل النتيجة نفسها في كل مرة.",
  "Free · no key": "مجاني · بلا مفتاح",
