  "It remembers everything and can search it": "يتذكّر كل شيء ويستطيع البحث فيه",
  "Learns your vocabulary and writes the way you do": "يتعلّم مفرداتك ويكتب بطريقتك",
  "Long answers": "إجابات طويلة",
