  "Not running": "لا يعمل",
  "Running": "يعمل",
  "Loading the model…": "جارٍ تحميل النموذج…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "لا شيء في التطبيق يستطيع الوصول إلى الإنترنت — لا بحث على الويب، ولا خرائط، ولا تنزيلات. ويستمر النموذج وكل ما على الهاتف في العمل.",
  "Offline lock": "قفل عدم الاتصال",
  "Same question, same answer": "نفس السؤال، نفس الإجابة",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "يفكّر النموذج أولًا في كل سؤال. أفضل بوضوح في المسائل الصعبة، لكن على الهاتف تبدأ الإجابة بعد 30–90 ثانية. عند الإيقاف: اضغط «التفكير» فقط في الأسئلة التي تحتاجه.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "النموذج نفسه الموجود بالأسفل، مع ذاكرة تتسع لكتاب كامل من السياق دفعة واحدة. على جهاز بذاكرة 48 جيجابايت، تُستغل الذاكرة الإضافية في السياق أفضل من الدقة — يمكنك إعطاؤه عقدًا كاملًا أو ملاحظات سنة كاملة ويبقيها كلها في متناوله.",
  "The whole assistant, on your device": "المساعد كاملًا، على جهازك",
  "Works entirely offline. No account, ever.": "يعمل بالكامل بدون إنترنت. بلا حساب على الإطلاق.",
