  "What should it do? e.g. “A function that finds a crane's capacity at any radius from a load chart table”": "ماذا يجب أن يفعل؟ مثلًا «دالة تحسب حمولة الرافعة عند أي نصف قطر من جدول الأحمال»",
  "Writing the program and its tests…": "جارٍ كتابة البرنامج واختباراته…",
