  "Previous page": "الصفحة السابقة",
  "No page contains that.": "لا توجد صفحة تحتوي على ذلك.",
  "Only the first parts of this long document were summarised.": "لُخّصت الأجزاء الأولى فقط من هذا المستند الطويل.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "افتح ملف PDF أو Word أو كتابًا أو صفحة ويب. اقرأه هنا وتحادث معه — كل إجابة تُظهر الصفحة التي جاءت منها. ويبقى كل شيء على هاتفك.",
  "Open a file": "فتح ملف",
  "Opened before": "فُتحت من قبل",
  "Page {n}": "الصفحة {n}",
  "Pick a PDF, Word, PowerPoint, e-book, web page or text file.": "اختر ملف PDF أو Word أو PowerPoint أو كتابًا إلكترونيًا أو صفحة ويب أو ملفًا نصيًا.",
  "Pick the file again to continue — files are not copied into the app.": "اختر الملف مرة أخرى للمتابعة — لا تُنسخ الملفات داخل التطبيق.",
  "Read pages": "الصفحات المقروءة",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "القراءة والبحث يعملان الآن. للتحادث مع الملف، ثبّت نموذجًا من «المحرك».",
  "Reading pages {p}…": "جارٍ قراءة الصفحات {p}…",
  "Reading part {i} of {n} (pages {a}–{b})…": "جارٍ قراءة الجزء {i} من {n} (الصفحات {a}–{b})…",
  "Search in this file…": "ابحث في هذا الملف…",
  "Something went wrong: {e}": "حدثت مشكلة: {e}",
  "Text of page {n}": "نص الصفحة {n}",
  "That file is too big (60 MB at most).": "الملف كبير جدًا (60 ميجابايت كحد أقصى).",
  "The AI is reading scanned page {n}…": "يقرأ الذكاء الاصطناعي الصفحة الممسوحة ضوئيًا {n}…",
  "There is no readable text in this file.": "لا يوجد نص مقروء في هذا الملف.",
  "This answer could not be tied to a page — check the pages listed below before relying on it.": "تعذّر ربط هذه الإجابة بصفحة — راجع الصفحات المذكورة بالأسفل قبل الاعتماد عليها.",
  "Writing the answer…": "جارٍ كتابة الإجابة…",
  "{n} page reference(s) the AI made up were removed.": "حُذفت {n} إشارة إلى صفحات اختلقها الذكاء الاصطناعي.",
  "{n} page(s) match": "{n} صفحة مطابقة",
  "{n} scanned": "{n} ممسوحة",
  "Copy this page": "نسخ هذه الصفحة",
  "Read a PDF or book and chat with it — every answer shows its page": "اقرأ ملف PDF أو كتابًا وتحادث معه — كل إجابة تُظهر صفحتها",
  "Summarise this document": "لخّص هذا المستند",
  "What are the key points?": "ما النقاط الرئيسية؟",
  "Checklist: what every answer must satisfy (one per line, optional)": "قائمة مراجعة: ما يجب أن تحققه كل إجابة (بند في كل سطر، اختياري)",
  "Facts the AI should know (prices, rules, terms — optional)": "معلومات يجب أن يعرفها الذكاء الاصطناعي (أسعار، قواعد، شروط — اختياري)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "افصل بين المواضيع بسطر فارغ. لا تُستخدم إلا الفقرات التي تناسب السؤال، لذا يمكن أن يكون طويلًا.",
  "Facts": "المعلومات",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "ويشغّل أيضًا هذا البرنامج الصغير على هاتفك (بدون إنترنت، في بيئة معزولة — بلا وصول إلى الإنترنت أو الملفات أو التطبيق)",
  "Edit or improve my CV": "تعديل سيرتي الذاتية أو تحسينها",
  "Say what to add or change («add my job at XCMG as crane supervisor, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "اكتب ما تريد إضافته أو تغييره («أضف عملي في XCMG مشرفًا للرافعات، 2019–2022»، «غيّر رقم هاتفي إلى …»)، أو اتركه فارغًا لجعلها أكثر احترافية فقط. سترى النتيجة قبل حفظها.",
  "What should be added or changed? (optional)": "ما الذي تريد إضافته أو تغييره؟ (اختياري)",
  "Apply my change": "تطبيق تعديلي",
