  "Done — you can undo it": "تم — يمكنك التراجع",
  "Undo the last change": "التراجع عن آخر تعديل",
  "Stuck — starting again from scratch with a different approach": "تعثّر — سأبدأ من جديد بطريقة مختلفة.",
  "Wrote it, with {n} tests.": "كتبه مع {n} اختبارات.",
