  "The fix deleted the tests — refused.": "حذف الإصلاحُ الاختبارات — فرُفض.",
  "The model answered without any code — try asking again in other words.": "أجاب النموذج بلا أي كود — جرّب السؤال مرة أخرى بصياغة مختلفة.",
  "A picture — Studio draws it on this phone": "صورة — يرسمها «الاستوديو» على هذا الهاتف",
