  "Could not open that picture": "تعذّر فتح هذه الصورة",
  "Could not save": "تعذّر الحفظ",
  "Create": "إنشاء",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "صور بجودة حديثة في 4 خطوات: أشخاص وأماكن ومنتجات ونصوص داخل الصورة. ويعدّل أيضًا صورة تعطيه إياها («اجعلها ليلًا»، «أزِل السيارة»).",
  "Describe the picture, in Arabic or English — e.g. “a Liebherr crane lifting a bridge beam at sunset”": "صِف الصورة بالعربية أو الإنجليزية — مثلًا «رافعة ليبهر ترفع كمرة جسر وقت الغروب»",
