  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "لا يحتوي هذا الإصدار من Attune على محرك صور يعمل على شريحة الرسوميات، فتُرسم الصور على المعالج (أبطأ). وسيضيفه تحديث قادم.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "توقف محرك الصور عن الاستجابة أثناء تحميل النموذج، فأُوقف. تجد آخر سطوره في «المحرك» ← «سجل المحرك» — أرسلها إلى الدعم.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "لم يستجب تعريف GPU في هذا الهاتف، فتُرسم الصور على المعالج (أبطأ).",
  "What should change? e.g. “make it night, with the site lights on”": "ما الذي يتغيّر؟ مثلًا «اجعلها ليلًا مع إضاءة الموقع»",
