  "I couldn't open {f} on the phone: {why}\n\nTry saving it as .xlsx or .csv and attach it again.": "تعذّر فتح {f} على الهاتف: {why}\n\nجرّب حفظه بصيغة ‎.xlsx أو ‎.csv وأرفقه مرة أخرى.",
