  "Starter questions (one per line, optional)": "أسئلة للبدء (سؤال في كل سطر، اختياري)",
  "Assistants are experts you set up once — their instructions are used in every chat you start with them.": "المساعدون خبراء تجهّزهم مرة واحدة — وتُستخدم تعليماتهم في كل محادثة تبدؤها معهم.",
  "New assistant": "مساعد جديد",
