  "e.g. We are bidding for a 3-month crane contract. Prices in EGP, VAT 14%. Answer as our commercial manager.": "مثلًا: نتقدّم لعقد رافعات لمدة 3 أشهر. الأسعار بالجنيه، وضريبة القيمة المضافة 14%. أجب بصفتك مديرنا التجاري.",
  "All projects": "كل المشاريع",
