  "This is the design. Tap any table or field name to rename it — you can change everything else after creating it.": "هذا هو التصميم. اضغط على اسم أي جدول أو حقل لتغيير اسمه — ويمكنك تغيير أي شيء آخر بعد الإنشاء.",
