  "Linked {t} ({n})": "{t} المرتبطة ({n})",
  "Connections between tables": "الروابط بين الجداول",
  "None yet — add a field of type “Link to another table”, or ask below: “connect Jobs to Customers”.": "لا يوجد بعد — أضف حقلًا من نوع «رابط لجدول آخر»، أو اطلب بالأسفل: «اربط الأعمال بالعملاء».",
  "Count": "العدد",
  "No records match": "لا توجد سجلات مطابقة",
  "Ask your data — like an Access query, in words": "اسأل بياناتك — مثل استعلام Access، ولكن بالكلام",
  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "مثلًا: الفواتير غير المدفوعة فوق 50,000 · أعمال هذا الشهر حسب العميل · أعلى 5 رافعات إيرادًا",
  "Load a model to ask your data in words.": "حمّل نموذجًا لتسأل بياناتك بالكلام.",
  "Query saved": "تم حفظ الاستعلام",
  "Save query": "حفظ الاستعلام",
  "Saved queries": "الاستعلامات المحفوظة",
  "Describe a form — the fields to fill, in order": "صِف نموذج إدخال — الحقول المطلوب ملؤها بالترتيب",
  "e.g. a quick job form for the site: customer, crane, start date, days — status New": "مثلًا: نموذج سريع للموقع: العميل، والرافعة، وتاريخ البدء، والأيام — والحالة «جديد»",
  "Make the form": "إنشاء النموذج",
  "Load a model to make forms in words.": "حمّل نموذجًا لإنشاء نماذج الإدخال بالكلام.",
  "Form saved — pick it above the records when you add one": "حُفظ النموذج — اختره فوق السجلات عند إضافة سجل",
  "Save form": "حفظ النموذج",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "لا توجد نماذج إدخال بعد. يعرض النموذج الحقول التي تحتاجها فقط، بترتيبك، وبقيم جاهزة — اختره عند إضافة سجل.",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "أحضِر المحادثة من {t} — الصق المحادثة كاملة أو آخر رد فقط:",
  "Paste here…": "الصق هنا…",
  "Read it & suggest my reply": "اقرأها واقترح ردّي",
  "Pasted from {t}": "منسوخ من {t}",
  "Copy & open {t}": "النسخ وفتح {t}",
  "Queries": "الاستعلامات",
  "Forms": "النماذج",
  "Open an app file (made with Attune)": "فتح ملف تطبيق (مُنشأ بـ Attune)",
  "That file isn't an app made with Attune Business.": "هذا الملف ليس تطبيقًا مُنشأً بـ Attune الأعمال.",
  "Updated from the app file — {n} tables with their records": "تم التحديث من ملف التطبيق — {n} جداول ببياناتها",
  "Opened — {n} tables with their records": "تم الفتح — {n} جداول ببياناتها",
  "Change the design in words — add fields to any table, new tables, links…": "غيّر التصميم بالكلام — أضف حقولًا لأي جدول، أو جداول جديدة، أو روابط…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "مثلًا: أضف البريد الإلكتروني والرقم الضريبي إلى «الموردون»، وحقل أشهر الضمان إلى «قطع الغيار»",
  "Saved — send this file; it opens in any browser, no Attune needed": "حُفظ — أرسل هذا الملف؛ يُفتح في أي متصفح دون الحاجة إلى Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "ملفات Excel تحتاج Python، وهو غير متوفر في هذه النسخة — استخدم CSV.",
  "Making the Excel file…": "جارٍ إنشاء ملف Excel…",
  "Couldn't make the Excel file: {e}": "تعذّر إنشاء ملف Excel: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "أعطِه لفريقك كتطبيق: ملف واحد يحتوي على كل البيانات — يُفتح في متصفح أي هاتف أو حاسوب دون الحاجة إلى Attune. وعندما تحتاج إلى تغيير شيء، افتح الملف هنا («الأعمال» ← «فتح ملف تطبيق»)، واطلب ذلك من الذكاء الاصطناعي، ثم أرسل التطبيق الجديد.",
  "Export as an app": "التصدير كتطبيق",
  "Excel workbook (all tables)": "مصنّف Excel (كل الجداول)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "توقف محرك الصور قبل اكتمال الصورة — ربما أغلقه أندرويد لتوفير الذاكرة. جرّب «مسودة سريعة»، أو أغلق التطبيقات الأخرى وحاول مرة أخرى.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "تعذّر إنشاء الصورة. افتح «المحرك» ← «سجل المحرك» وأرسل لي ما فيه.",
  "Multi-token prediction (faster writing)": "التوقع متعدد الكلمات (كتابة أسرع)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "متوقف افتراضيًا: على بعض الهواتف يكرر الكلمات والأرقام («ItIt is is»، «20205»). فعّله فقط إذا ظلت الإجابات صحيحة.",
