  "Free gives you {n} answers a day on every model. Pro removes every limit:": "تمنحك الخطة المجانية {n} إجابة يوميًا على كل النماذج. ويُزيل Pro كل الحدود:",
  "Unlimited answers — no daily limit": "إجابات بلا حدود — بلا حد يومي",
