  "Everything runs on your phone: no account, nothing uploaded. Your plan is checked on the phone, even offline.": "كل شيء يعمل على هاتفك: بلا حساب، ولا يُرفع أي شيء. ويُتحقَّق من خطتك على الهاتف، حتى بدون إنترنت.",
  "Your Pro plan has ended — renew it any time in Plan.": "انتهت خطة Pro — يمكنك تجديدها في أي وقت من «الخطة».",
  "Older keys can't be checked on this version — ask the seller for an activation code.": "لا يمكن التحقق من المفاتيح القديمة في هذا الإصدار — اطلب من البائع رمز تفعيل.",
