  "Explicit action verbs beat vague asks (Anthropic 2026)": "الأفعال الواضحة أفضل من الطلبات المبهمة (Anthropic 2026)",
  "State the desired outcome, not steps (OpenAI 2026)": "اذكر النتيجة المطلوبة، لا الخطوات (OpenAI 2026)",
  "Concise prompts cut cost ~76% and lift quality": "الطلبات الموجزة توفّر نحو 76% من التكلفة وترفع الجودة",
  "Style examples outperform adjectives like 'professional'": "أمثلة الأسلوب أفضل من صفات مثل «احترافي»",
