  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "يرسم «الاستوديو» على المعالج (ببطء). في هذا الهاتف شريحة رسوميات — جرّبها: الصور والتوضيح ×4 أسرع عليها بمرات كثيرة.",
