  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "توقف تعريف شريحة الرسوميات مرتين أثناء تحميل نموذج الصور، فنقل Attune «الاستوديو» إلى المعالج (يمكنك تجربة شريحة الرسوميات مرة أخرى بالأسفل).",
