  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "عندما يحتوي عمود في جدول على أسماء سجلات من جدول آخر (عميل العمل، أو رافعة الفاتورة)، يكتشفه الهاتف هنا ويربطهما — دون أن ترسم العلاقات يدويًا.",
