  "Without the graphics chip, the ×4 AI sharpen takes about {m} minutes on this phone. “×2 sharper” takes a second. Start the ×4?": "بدون شريحة الرسوميات يستغرق التوضيح ×4 بالذكاء الاصطناعي نحو {m} دقيقة على هذا الهاتف، بينما يستغرق «توضيح ×2» ثانية. هل تريد بدء ×4؟",
  "Highest resolution — sharpen every picture (×4 with the graphics chip; an instant ×2 without it)": "أعلى دقة — توضيح كل صورة (×4 مع شريحة الرسوميات؛ و×2 فوري بدونها)",
