  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "صِفه في جملة — يكتب الذكاء الاصطناعي على هاتفك عرض PowerPoint مصمّمًا أو تقريرًا كاملًا، من الإنترنت أو من ملفك. عدّل أي شريحة، ثم احفظه بصيغة PowerPoint أو Word أو PDF.",
  "Presentation": "عرض تقديمي",
