  "e.g. Monthly report on our crane fleet: utilisation, breakdowns, costs and what to fix next month": "مثلًا: تقرير شهري عن أسطول الرافعات: التشغيل، والأعطال، والتكاليف، وما يجب إصلاحه الشهر القادم",
  "Who is it for? (optional) — e.g. investors, clients, my team": "لمن هو؟ (اختياري) — مثلًا: مستثمرون، أو عملاء، أو فريقي",
