  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "من تطبيق المفكرة على الهاتف: افتح ملاحظة (أو اختر عدة ملاحظات) ← مشاركة ← Attune ← «الحفظ في الرف». أو اختر ملفات مُصدَّرة من هنا: نص، Word، PDF، صفحات ويب، Google Keep، Evernote، ملف ‎.zip، أو صور ملاحظات.",
  "Versions & prices": "الفئات والأسعار",
